@Composable
fun DetailScreen(productId: Int, onBuyNow: (Int) -> Unit, modifier: Modifier = Modifier) {
    var product by remember { mutableStateOf<Product?>(null) }
    var dealMessage by rememberSaveable { mutableStateOf<String?>(null) }
    var dealAnnounced by rememberSaveable { mutableStateOf(false) }
    LaunchedEffect(productId) {
        val loaded = ProductRepository.byId(productId)
        product = loaded
        if (loaded.dealPercent > 0 && !dealAnnounced) {
            dealAnnounced = true
            dealMessage = "${loaded.dealPercent}% off ${loaded.name}, today only."
        }
    }

    dealMessage?.let { message ->
        AlertDialog(
            onDismissRequest = { dealMessage = null },
            title = { Text("Deal unlocked") },
            text = { Text(message) },
            confirmButton = { TextButton(onClick = { dealMessage = null }) { Text("Nice") } },
        )
    }

